<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';$pdo=db();$user=currentUser();$message='';$error='';function roleKey(string $value):string{$value=mb_strtolower(trim($value));$value=preg_replace('/^sr\.?\s+/','senior ',$value);return preg_replace('/\s+/',' ',$value);}
if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){try{$action=$_POST['action']??'';$profile=(int)($_POST['profile_id']??0);$owned=$pdo->prepare('SELECT name FROM wishlist_profiles WHERE id=? AND user_id=?');$owned->execute([$profile,$user['id']]);$profileName=(string)$owned->fetchColumn();if($profile&&!$profileName)throw new RuntimeException('Invalid profile.');if($action==='create_profile'){$name=trim($_POST['profile_name']??'');if(!$name)throw new RuntimeException('Profile name is required.');$pdo->prepare('INSERT IGNORE INTO wishlist_profiles(user_id,name) VALUES(?,?)')->execute([$user['id'],$name]);$message='Profile created.';}elseif($action==='add'){$candidate=$_POST['candidate_id']??'';$s=$pdo->prepare('SELECT role_title FROM candidates WHERE id=?');$s->execute([$candidate]);$role=(string)$s->fetchColumn();if(!$role||roleKey($role)!==roleKey($profileName))throw new RuntimeException('Candidate can only be added to the job they applied for.');$pdo->prepare("INSERT INTO wishlist_items(profile_id,candidate_id,disposition) VALUES(?,?,'wishlist') ON DUPLICATE KEY UPDATE disposition=IF(disposition='blacklisted',disposition,'wishlist')")->execute([$profile,$candidate]);$message='Candidate added to '.$profileName.'.';}elseif($action==='status'){$status=$_POST['status']??'';if(!in_array($status,['wishlist','selected','blacklisted'],true))throw new RuntimeException('Invalid status.');$pdo->prepare('UPDATE wishlist_items SET disposition=? WHERE profile_id=? AND candidate_id=?')->execute([$status,$profile,$_POST['candidate_id']??'']);$message='Candidate status updated.';}elseif($action==='email'){$ids=array_values(array_unique(array_filter($_POST['candidate_ids']??[])));$subject=trim($_POST['subject']??'');$body=trim($_POST['body']??'');$date=trim($_POST['interview_date']??'');$time=trim($_POST['interview_time']??'');$timezone=trim($_POST['timezone']??'Asia/Kolkata');if(!$ids||!$subject||!$body)throw new RuntimeException('Select candidates and complete the preview.');$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT c.id,c.email FROM candidates c JOIN wishlist_items wi ON wi.candidate_id=c.id WHERE wi.profile_id=? AND wi.disposition='wishlist' AND c.id IN ($marks)");$s->execute(array_merge([$profile],$ids));$recipients=$s->fetchAll();if(!$recipients)throw new RuntimeException('Selected candidates need valid wishlist status.');$interviewAt=($date&&$time)?$date.' '.$time.':00':null;$dedupe=hash('sha256',$user['id'].'|'.$profile.'|'.$subject.'|'.$body.'|'.$interviewAt.'|'.implode(',',$ids));$pdo->beginTransaction();$pdo->prepare("INSERT INTO email_batches(user_id,profile_id,subject,body,interview_at,timezone,recipient_count,status,dedupe_key) VALUES(?,?,?,?,?,?,?,'preview',?)")->execute([$user['id'],$profile,$subject,$body,$interviewAt,$timezone,count($recipients),$dedupe]);$batch=$pdo->lastInsertId();$ri=$pdo->prepare("INSERT INTO email_recipients(batch_id,candidate_id,email,status) VALUES(?,?,?,'preview')");foreach($recipients as $r)if($r['email'])$ri->execute([$batch,$r['id'],$r['email']]);$pdo->commit();$message='Email preview saved for '.count($recipients).' candidates.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=str_contains($e->getMessage(),'Duplicate entry')?'This exact preview already exists.':$e->getMessage();}}
$profilesStmt=$pdo->prepare('SELECT wp.*,COUNT(wi.id) total FROM wishlist_profiles wp LEFT JOIN wishlist_items wi ON wi.profile_id=wp.id WHERE wp.user_id=? GROUP BY wp.id ORDER BY wp.name');$profilesStmt->execute([$user['id']]);$profiles=$profilesStmt->fetchAll();$active=(int)($_GET['profile']??$_POST['profile_id']??($profiles[0]['id']??0));$activeName='';foreach($profiles as $p)if((int)$p['id']===$active)$activeName=$p['name'];$all=loadCandidateRecords();$eligible=array_values(array_filter($all,fn($c)=>roleKey($c['role']??'')===roleKey($activeName)));$itemStmt=$pdo->prepare('SELECT candidate_id,disposition FROM wishlist_items WHERE profile_id=?');$itemStmt->execute([$active]);$statuses=[];foreach($itemStmt->fetchAll() as $r)$statuses[$r['candidate_id']]=$r['disposition'];$items=array_values(array_filter($eligible,fn($c)=>isset($statuses[$c['id']])));usort($items,fn($a,$b)=>$b['score']<=>$a['score']);$activePage='wishlist';$pageTitle='Wishlist · ResumeIQ';$pageStyles='<style>.profiles{display:flex;gap:8px;overflow-x:auto;margin:12px 0}.profile{min-width:190px;padding:11px;border:1px solid var(--line);border-radius:9px;background:#fff}.profile.active{background:var(--primary-soft);border-color:#d8ceff}.profile strong{display:block;font-size:10px}.profile span{font-size:8px;color:var(--muted)}.wish-grid{display:grid;grid-template-columns:1fr 390px;gap:10px}.wish-list,.preview{padding:16px}.candidate{display:grid;grid-template-columns:25px 1fr 58px auto;gap:8px;align-items:center;padding:11px 0;border-bottom:1px solid var(--line)}.candidate strong{font-size:10px}.candidate p{font-size:8px;color:var(--muted);margin:3px 0}.rank-label{font-size:8px;color:var(--primary);font-weight:700}.actions{display:flex;gap:5px}.mini{height:29px;border:1px solid var(--line);border-radius:7px;background:#fff}.preview textarea{min-height:140px}.preview-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.notice{padding:10px;border-radius:8px;margin:10px 0;font-size:10px}.ok{background:var(--green-soft);color:var(--green)}.err{background:#fff1f3;color:var(--danger)}@media(max-width:850px){.wish-grid{grid-template-columns:1fr}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-heart"></i> Job-specific shortlist</div><h1>Wishlist & email</h1><p>Candidates only appear under the job they applied for. First 5 are primary, next 5 substitutes.</p></div><form method="post" style="display:flex;gap:7px"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="create_profile"><input class="control" name="profile_name" placeholder="New job profile" required><button class="btn">Create</button></form></section><?php if($message):?><div class="notice ok"><?=htmlspecialchars($message)?></div><?php endif?><?php if($error):?><div class="notice err"><?=htmlspecialchars($error)?></div><?php endif?><nav class="profiles"><?php foreach($profiles as $p):?><a class="profile <?=$active===(int)$p['id']?'active':''?>" href="?profile=<?=$p['id']?>"><strong><?=htmlspecialchars(trim($p['name']))?></strong><span><?=(int)$p['total']?> shortlisted · <?=count(array_filter($all,fn($c)=>roleKey($c['role']??'')===roleKey($p['name'])))?> eligible resumes</span></a><?php endforeach?></nav>
<section class="panel" style="padding:13px;margin-bottom:10px"><form method="post" style="display:flex;gap:8px"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="add"><input type="hidden" name="profile_id" value="<?=$active?>"><select class="control" name="candidate_id" required><option value="">Add <?=$activeName?htmlspecialchars(trim($activeName)):'candidate'?> applicant…</option><?php foreach($eligible as $c):if(isset($statuses[$c['id']]))continue;$d=candidatePresentation($c);?><option value="<?=htmlspecialchars($c['id'])?>"><?=htmlspecialchars($d['name'])?> · <?=$c['score']?>%</option><?php endforeach?></select><button class="btn btn-primary"><i class="fa-solid fa-plus"></i>Add to wishlist</button></form></section><section class="wish-grid"><article class="panel wish-list"><h2>Candidates</h2><?php if(!$items):?><div class="empty">No marked candidates in this job profile. Use the dropdown above or add from candidate details.</div><?php endif?><form method="post" id="mailForm"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="email"><input type="hidden" name="profile_id" value="<?=$active?>"><?php foreach($items as $i=>$c):$d=candidatePresentation($c);$status=$statuses[$c['id']];?><div class="candidate"><input type="checkbox" name="candidate_ids[]" value="<?=htmlspecialchars($c['id'])?>" <?=$status!=='wishlist'?'disabled':''?>><div><strong><a href="candidate_detail.php?id=<?=urlencode($c['id'])?>"><?=htmlspecialchars($d['name'])?></a></strong><p><?=htmlspecialchars($d['role'])?> · <?=htmlspecialchars($c['email']??'No email')?> · <?=htmlspecialchars($status)?></p><span class="rank-label"><?=$i<5?'Primary '.($i+1):($i<10?'Substitute '.($i-4):'Reserve')?></span></div><span class="badge"><?=$c['score']?>%</span><div class="actions"><button class="mini" type="button" onclick="statusUpdate('<?=htmlspecialchars($c['id'])?>','selected')" title="Selected"><i class="fa-solid fa-check"></i></button><button class="mini" type="button" onclick="statusUpdate('<?=htmlspecialchars($c['id'])?>','blacklisted')" title="Blacklist"><i class="fa-solid fa-ban"></i></button></div></div><?php endforeach?></form></article><aside class="panel preview"><h2>Email preview</h2><label>Subject</label><input class="control" form="mailForm" name="subject" value="Interview invitation" required><div class="preview-grid"><div><label>Date</label><input class="control" form="mailForm" type="date" name="interview_date"></div><div><label>Time</label><input class="control" form="mailForm" type="time" name="interview_time"></div></div><label>Timezone</label><select class="control" form="mailForm" name="timezone"><option>Asia/Kolkata</option><option>UTC</option></select><label>Message</label><textarea class="control" form="mailForm" name="body" required>Hello {{candidate_name}},&#10;&#10;We would like to invite you for an interview on {{interview_date}} at {{interview_time}}.&#10;&#10;Regards,&#10;Hiring Team</textarea><div style="display:flex;gap:8px;margin-top:9px"><button class="btn" type="button" onclick="document.querySelectorAll('#mailForm [name=&quot;candidate_ids[]&quot;]:not(:disabled)').forEach((x,i)=>x.checked=i<5)">Select primary 5</button><button class="btn btn-primary" form="mailForm">Save email preview</button></div></aside></section><form method="post" id="statusForm" hidden><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="status"><input type="hidden" name="profile_id" value="<?=$active?>"><input name="candidate_id"><input name="status"></form><script>function statusUpdate(id,status){const f=document.getElementById('statusForm');f.candidate_id.value=id;f.status.value=status;f.submit()}</script>
